package main

import (
  "fmt"
  "io"
  "net/http"
)

func main() {
  req, err := http.NewRequest("GET", "https://api.example.com/users", nil)
  if err != nil { panic(err) }
  res, err := http.DefaultClient.Do(req)
  if err != nil { panic(err) }
  defer res.Body.Close()
  data, _ := io.ReadAll(res.Body)
  fmt.Println(res.Status, string(data))
}

