package main

import (
  "bytes"
  "fmt"
  "io"
  "mime/multipart"
  "net/http"
  "os"
)

func main() {
  body := &bytes.Buffer{}
  writer := multipart.NewWriter(body)
  writer.WriteField("title", "Quarterly \"report\"")
  {
    file, err := os.Open("/tmp/dir/report.pdf")
    if err != nil { panic(err) }
    defer file.Close()
    part, err := writer.CreateFormFile("attachment", "report.pdf")
    if err != nil { panic(err) }
    io.Copy(part, file)
  }
  writer.WriteField("at", "@notafile")
  {
    file, err := os.Open("/tmp/we;ird,\"n\".txt")
    if err != nil { panic(err) }
    defer file.Close()
    part, err := writer.CreateFormFile("odd", "we;ird,\"n\".txt")
    if err != nil { panic(err) }
    io.Copy(part, file)
  }
  writer.Close()
  req, err := http.NewRequest("POST", "https://api.example.com/users", body)
  if err != nil { panic(err) }
  req.Header.Set("Content-Type", writer.FormDataContentType())
  res, err := http.DefaultClient.Do(req)
  if err != nil { panic(err) }
  defer res.Body.Close()
  data, _ := io.ReadAll(res.Body)
  fmt.Println(res.Status, string(data))
}

